head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;
scwin.LastJob = "";
scwin.vScrenID = 'ULDSTF31100.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    dts_EMP_NO.DataID = "/CodeAction.do?method=getAllEmpNoDepCode&inputMessageId=CODE_EMPDEP_IN&For=R&DEP_CD=" + scwin.gDepCd;
    dts_EMP_NO.Reset();
    dts_DEP_CD.DataID = "/CodeAction.do?method=getDepUpCode&inputMessageId=CODE_EMPDEP_IN&For=R&DEP_CD=" + scwin.gDepCd;
    dts_DEP_CD.Reset();

    //2009.09.01 채권공시 - 채권상장팀인경우..전체를 밴다..
    if (js_bond_yn == "Y") {
        $c.cp.removeRow(dts_DEP_CD, 1);
    }
};
scwin.fn_SetHeader = function() {
    // CUD용 Header
    dts_Save.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=APPROV_AUTH_IN";
    dts_Save.Reset();
    dts_Save.insertRow();
};
scwin.fn_List = function() {
    dts_Approv_Auth_List.DataID = "/DisclosureTransmitAuthority.do?method=listDisclosureTransmitAuthority" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_Approv_Auth_List.Reset();
    //alert(dts_Approv_Auth_List.Text);

};
scwin.fn_CheckForm = function() {
    if ($c.stf.getObjectValue(cmb_DEP_CD) == "") {
        $c.win.alert("[팀]을 선택하세요.");
        cmb_DEP_CD.focus();
        return;
    }
    if ($c.stf.getObjectValue(cmb_EMP_NO) == "") {
        $c.win.alert("[담당자]을 선택하세요.");
        cmb_EMP_NO.focus();
        return;
    }
    if (edt_SDate.getValue() == "") {
        $c.win.alert("[시작일시]를 입력하세요.");
        edt_SDate.focus();
        return;
    }
    if (edt_EDate.getValue() == "") {
        $c.win.alert("[만료일시]를 입력하세요.");
        edt_EDate.focus();
        return;
    }
    if (txb_Reason.getValue() == "") {
        $c.win.alert("[사유]를 입력하세요.");
        txb_Reason.focus();
        return;
    }
    var res = window.confirm("저장하시겠습니까?");
    if (res) {
        scwin.fn_Save();
    }
};
scwin.fn_Save = function() {

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

    scwin.LastJob = "저장"; /*ORG SRC: dts_Save.UserStatus(1) = TB_JOB_INSERT;*/ X = TB_JOB_INSERT;
    dts_Save.setCellData(1, "LST_CHG_EMP_NO", scwin.gEmpNo);
    trs_Save.Action = "/DisclosureTransmitAuthority.do?method=setDisclosureTransmitAuthority" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_Save)";
    trs_Save.Post();
};
scwin.fn_Delete = function(row, colid) {
    if ((colid == "FUNC_DEL") &&
        (row > 0) &&
        (dts_Approv_Auth_List.getCellData(row, "FUNC_DEL") != "")) {
        var res = window.confirm("삭제하시겠습니까?");
        if (res) {
            scwin.LastJob = "삭제";
            var str_AUTH_ENTRUST_USR_ID = dts_Approv_Auth_List.getCellData(row, "AUTH_ENTRUST_USR_ID");
            var str_AUTH_ENTRUSTED_USR_ID = dts_Approv_Auth_List.getCellData(row, "AUTH_ENTRUSTED_USR_ID");
            var str_AUTH_END_DD = dts_Approv_Auth_List.getCellData(row, "AUTH_END_DD");
            var str_AUTH_STRT_DD = dts_Approv_Auth_List.getCellData(row, "AUTH_STRT_DD");
            var str_LST_CHG_DDTM = dts_Approv_Auth_List.getCellData(row, "LST_CHG_DDTM");
            //alert(str_AUTH_ENTRUST_USR_ID + ", " + str_AUTH_ENTRUSTED_USR_ID + ", " + str_AUTH_END_DD + ", " + str_AUTH_STRT_DD);		


            // ********************************************************************
            // [WebSquare 전환 추가] 원본 소스와 비교 필요
            // 
            // ********************************************************************

            /*ORG SRC: dts_Save.UserStatus(1) = TB_JOB_DELETE;*/
            X = TB_JOB_DELETE;
            dts_Save.setCellData(1, "AUTH_ENTRUST_USR_ID", str_AUTH_ENTRUST_USR_ID);
            dts_Save.setCellData(1, "AUTH_ENTRUSTED_USR_ID", str_AUTH_ENTRUSTED_USR_ID);
            dts_Save.setCellData(1, "AUTH_END_DD", str_AUTH_END_DD);
            dts_Save.setCellData(1, "AUTH_STRT_DD", str_AUTH_STRT_DD);
            dts_Save.setCellData(1, "LST_CHG_DDTM", str_LST_CHG_DDTM);

            //alert_parse(dts_Save.Text, ",");return;

            //alert(dts_Save.Text);

            trs_Save.Action = "/DisclosureTransmitAuthority.do?method=delDisclosureTransmitAuthority" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
            trs_Save.KeyName = "toinb_dataid4";
            trs_Save.KeyValue = "JSP(I:pInput=dts_Save)";
            trs_Save.Post();
        }
    }
};
scwin.trs_Save_OnFail = function() {
    $c.win.alert(scwin.LastJob + " 실패");
    $c.stf.alert_error(trs_Save);
    dts_Save.Reset();
    dts_Save.insertRow(); // 성공일 때 Default로 한줄 추가해 놓는다.

};
scwin.trs_Save_OnSuccess = function() {
    $c.win.alert(scwin.LastJob + " 성공");
    dts_Save.Reset();
    dts_Save.insertRow(); // 성공일 때 Default로 한줄 추가해 놓는다.
    scwin.fn_List();
};
scwin.btn_Save_onclick = function() {
    scwin.fn_CheckForm();
};
scwin.btn_SDate_onclick = function() {
    popUpCalendar2(edt_SDate);
};
scwin.btn_EDate_onclick = function() {
    popUpCalendar2(edt_EDate);
};
scwin.dts_Approv_Auth_List_OnLoadCompleted = function(rowcount) {
    //if (rowcount > 0)
    //	grd_Approv_Auth_List.AutoResizeAllCol(true);
    var vTotalCnt = rowcount;
    $c.stf.FillGridHeaderTotalCnt(vTotalCnt, panel_page);
};
scwin.cmb_DEP_CD_OnSelChange = function() {
    dts_EMP_NO.sort("DEP_CD", 0);
    //dts_EMP_NO.sort(); // W-Craft 주석처리 
    dts_EMP_NO.UseFilter = true;
    dts_EMP_NO.Filter();
    if ($c.stf.getObjectValue(cmb_DEP_CD) == "") {
        $c.stf.setObjectValue(cmb_EMP_NO, "");
    }
};
scwin.dts_EMP_NO_OnFilter = function(row) {
    //  부서코드에  해당하는 사원을 가져온다.
    var vVal = $c.stf.getObjectValue(cmb_DEP_CD);
    if (vVal == "") {
        // 전체일 경우
        return true;
    } else {
        var vVal2 = dts_EMP_NO.getCellData(row, "dep_cd"); // 전체.
        if (vVal2 == "") return true; // 전체.
        return (vVal == vVal2) ? true : false;
    }
};
scwin.grd_Approv_Auth_List_OnDblClick = function(row, colid) {
    scwin.fn_Delete(row, colid);
};
scwin.gform_onload = function() {
    $c.libRoundPanel.PanelToGroupBox(panel_1);
    scwin.fn_SetCode();

    //2009.09.01 채권공시 - 채권상장팀인경우..채권상장팀만 나오도록 셋팅한다.
    if (scwin.gDepCd == "2430") {
        $c.stf.setObjectValue(cmb_DEP_CD, scwin.gDepCd);
    }
    scwin.fn_SetHeader();
    scwin.fn_List();
};
